'use strict';
site.firstVisit=false;site.membersState='ready';site.memberSaveScenario='success';site.originalOutcome='published';site.copyOutcome='published';
const workspaceMembers=Object.fromEntries(Object.keys(workspaces).map(id=>[id,site.members.map(m=>({...m}))]));
function selectWorkspace(id){if(!accessibleWorkspace(id))return false;resetWorkspaceContext();state.workspace=id;state.articleId=defaultArticle(id);state.lang='en';state.tab='all';state.query='';state.selected.clear();state.route='content';return true;}
function setMembershipScenario(value){membershipScenario=value;if(!accessibleWorkspace(state.workspace))selectWorkspace('personal');if(!accessibleWorkspace(site.chosenWorkspace))site.chosenWorkspace='personal';}
function workspaceChoices(chosen,flow){return availableWorkspaces().map(w=>`<button class="choice ${chosen===w.id?'selected':''}" data-flow="${flow}" data-flow-id="${w.id}"><span class="workspace-avatar">${w.kind==='personal'?'JC':w.name.slice(0,1)}</span><span><strong>${esc(w.name)}</strong><small>${w.kind==='personal'?txt('个人空间 · 独立内容和连接','Personal workspace · independent content and connections'):txt('组织工作区','Organization workspace')+' · '+w.role}</small></span>${chosen===w.id?icon('check'):icon('chevron')}</button>`).join('');}
function membershipNotice(){return membershipScenario==='unavailable'?notice(txt('组织列表暂时无法加载。个人空间仍可使用；重试不会新建或切换到其他组织。','The organization list could not be loaded. Your personal workspace remains available; retrying does not create or switch organizations.'))+flowButton('重试组织列表','Retry organizations','retry-membership','','quiet'):'';}
actions.workspace=()=>modal(txt('选择工作区','Choose a workspace'),`<p>${txt('内容、站点、连接与角色按工作区独立。','Content, sites, connections and roles are independent for each workspace.')}</p>${membershipNotice()}${workspaceChoices(state.workspace,'select-workspace')}`,btn('关闭','close-modal'));
flowHandlers['select-workspace']=id=>{closeModal();guard(()=>{if(selectWorkspace(id))render();});};
flowHandlers['retry-membership']=()=>{membershipScenario='multiple';closeModal();if(state.route==='onboarding')render();else actions.workspace();};
flowHandlers['onboarding-owner']=id=>{if(accessibleWorkspace(id)){site.chosenWorkspace=id;render();}};
function languageSites(owner){return ['en','zh'].map(lang=>`<div class="site-row">${icon('globe')}<div><strong>${lang==='en'?'English':'简体中文'}</strong><small>${publicationTarget(owner,lang).host}</small></div>${badge(isSiteReady(owner,lang)?txt('已开通','Provisioned'):txt('等待配置','Not provisioned'),isSiteReady(owner,lang)?'green':'amber',true)}${isSiteReady(owner,lang)?flowButton('查看站点','View site','open-public-site',owner+':'+lang,'sm quiet'):''}</div>`).join('');}
onboardingPage=function(){const steps=[txt('选择工作区','Choose a workspace'),txt('确认语言站点','Check language sites'),txt('开始创作','Start writing')];return `<div class="onboarding-wrap"><header>${entryBrand()}${interfaceLanguageControl()}</header><div class="onboarding-content"><nav class="onboarding-steps">${steps.map((s,i)=>`<span class="${site.onboardingStep===i+1?'active':''}"><b>${i+1}</b>${s}</span>`).join('')}</nav><div class="eyebrow">MAKE ROOM FOR YOUR IDEAS</div><h1>${steps[site.onboardingStep-1]}</h1><p>${txt('每个工作区和每个语言站点都独立保留自己的内容与权限。','Each workspace and language site keeps its own content and permissions.')}</p><section class="panel onboarding-panel">${site.onboardingStep===1?membershipNotice()+workspaceChoices(site.chosenWorkspace,'onboarding-owner'):site.onboardingStep===2?languageSites(site.chosenWorkspace)+notice(txt('站点由运维预先配置。未开通的语言仍可写草稿；选择工作区不会创建 Ghost。','Sites are provisioned by operations. You can draft in an unprovisioned language; choosing a workspace does not create Ghost.')):`<div class="onboard-success"><span class="success-check">${icon('check')}</span><h2>${esc(workspaceLabel(site.chosenWorkspace))}</h2><p>${txt('保存、提交和发布分别确认，中英文可以独立推进。','Saving, submitting and publishing are separate steps. English and Chinese progress independently.')}</p></div>`}</section><div class="onboarding-footer">${site.onboardingStep>1?btn('上一步','onboard-back'):''}${btn(site.onboardingStep===3?'进入工作区':'继续','onboard-next','primary','arrow')}</div></div></div>`;};pageRenderers.onboarding=onboardingPage;
actions['onboard-next']=()=>{if(!accessibleWorkspace(site.chosenWorkspace))return; if(site.onboardingStep<3){site.onboardingStep++;render();}else {selectWorkspace(site.chosenWorkspace);site.firstVisit=false;render();}};
actions['sign-in']=()=>{site.signedIn=true;site.loginError='';if(!accessibleWorkspace(state.workspace))selectWorkspace('personal');if(site.firstVisit){site.chosenWorkspace=state.workspace;site.onboardingStep=1;state.route='onboarding';}else state.route=['login','onboarding','blog','story'].includes(site.returnTo)?'content':site.returnTo;render();};
actions['sign-out']=()=>{closeModal();guard(()=>{site.returnTo=state.route;site.signedIn=false;state.rights=false;state.route='login';render();});};
settingsPage=function(){const c=site.settings[state.workspace];return titleBlock('A HOME FOR YOUR CONTENT','工作区设置',txt('查看当前工作区的公开资料和独立语言站点。','View this workspace’s public profile and independent language sites.'))+`<div class="settings-layout"><section class="panel settings-panel"><h2>${txt('公开资料','Public profile')}</h2><div class="modal-field"><label>${txt('站点名称','Site name')}</label><input value="${esc(c.name)}" readonly></div><div class="modal-field"><label>${txt('站点简介','Site description')}</label><textarea readonly>${esc(c.description)}</textarea></div>${notice(txt('当前资料来自部署配置，仅供查看。此处没有可用的在线保存接口。','This profile comes from deployment configuration and is read-only. Online profile editing is not currently available.'))}<h2 class="section-heading">${txt('语言与站点','Languages & sites')}</h2>${languageSites(state.workspace)}${notice(txt('两个语言对应两个 Ghost 实例，文章可关联，发布与开通状态互不覆盖。','The two languages use separate Ghost instances. Articles can be linked; publication and provisioning remain independent.'))}</section><aside class="panel aside-panel"><h2>${txt('管理边界','Management boundaries')}</h2><p>${txt('可发布内容不等于可管理成员。组织 Admin 身份与 Publisher 管理能力分别核验。','Publishing permission does not grant member management. Organization Admin identity and Publisher-management capability are checked separately.')}</p>${workspaceKind()==='organization'?routeButton('成员与权限','members','full'):''}</aside></div>`;};pageRenderers.settings=settingsPage;
actions['save-settings']=()=>toast(txt('资料由部署配置管理，当前只读。','The profile is managed through deployment configuration and is read-only.'));
let memberIntent=null;
function beginMemberChange(index){const owner=state.workspace,m=workspaceMembers[owner]?.[index];if(!canManagePublishers(owner)||site.membersState!=='ready'||!m||m.self||m.role==='admin')return false;memberIntent={owner,index,oldRole:m.role,newRole:m.role==='publisher'?'member':'publisher'};return true;}
function commitMemberChange(){const i=memberIntent;if(!i||i.owner!==state.workspace||!canManagePublishers(i.owner)||site.membersState!=='ready')return 'Permission or workspace changed';const m=workspaceMembers[i.owner][i.index];if(m.role!==i.oldRole)return 'Member role changed; refresh and retry';if(site.memberSaveScenario==='failure')return 'The role could not be saved; no change was made';m.role=i.newRole;memberIntent=null;return null;}
membersPage=function(){if(workspaceKind()==='personal')return titleBlock('YOUR OWN SPACE','成员与权限','个人内容和组织内容分别管理。')+emptyState(txt('个人空间只有自己','This is your personal workspace'),txt('切换到组织后查看相应成员与角色。','Choose an organization to view its members and roles.'),btn('切换工作区','workspace'));const rows=workspaceMembers[state.workspace];return titleBlock('THE PEOPLE BEHIND THE WORDS','成员与权限',txt('组织成员来自 NyxID，CMS 仅管理 Publisher 授权。','Organization membership comes from NyxID. The CMS manages Publisher grants only.'))+`<div class="role-explainer"><div><span class="role-label">Member</span><strong>${txt('写作与提交','Write & submit')}</strong><p>${txt('编辑自己的草稿，提交确定版本。','Edit your own drafts and submit exact versions.')}</p></div><div><span class="role-label">Publisher</span><strong>${txt('发布与分发','Publish & distribute')}</strong><p>${txt('处理自己的内容或已提交的授权版本。','Process your own content or authorized submissions.')}</p></div><div><span class="role-label">Admin</span><strong>${txt('组织权限管理','Organization permissions')}</strong><p>${txt('还需当前组织的管理能力，才可更改 Publisher。','The current organization’s management capability is also required to change Publisher grants.')}</p></div></div><section class="panel member-panel"><div class="section-heading"><h2>${esc(workspaceLabel())}</h2>${badge(canManagePublishers()?txt('可管理 Publisher','Can manage Publishers'):txt('当前只读','Read only'),'neutral')}</div>${site.membersState==='ready'?rows.map((m,i)=>`<div class="member-row"><span class="avatar">${m.initials}</span><div><strong>${m.name}</strong><small>${m.email}</small></div>${badge(m.self?state.role:m.role,'neutral')}${!m.self&&m.role!=='admin'&&canManagePublishers()?flowButton(m.role==='publisher'?'撤销发布权限':'授予发布权限',m.role==='publisher'?'Revoke publishing':'Grant publishing','member-change',String(i),'sm quiet'):'<span>NyxID</span>'}</div>`).join(''):notice(site.membersState==='loading'?txt('正在加载组织成员；暂不能修改权限。','Loading organization members; permissions cannot be changed yet.'):txt('成员列表加载失败。已有权限未改变，可以重试。','The member list could not be loaded. Existing permissions are unchanged; retry to continue.'))+flowButton('重试加载','Retry members','retry-members','','quiet')}</section>${notice(txt('管理能力与当前组织绑定；切换组织不会沿用上一组织的 Admin 身份。','Management capability belongs to the current organization. Switching organizations never carries over an Admin role.'))}`;};pageRenderers.members=membersPage;
flowHandlers['retry-members']=()=>{site.membersState='ready';render();};
flowHandlers['member-change']=index=>{if(!beginMemberChange(Number(index)))return;const m=workspaceMembers[memberIntent.owner][memberIntent.index];modal(txt('确认 Publisher 权限变更','Confirm Publisher permission change'),`<p>${workspaceLabel(memberIntent.owner)} · ${m.name}</p><p>${memberIntent.oldRole} → ${memberIntent.newRole}</p><p>${txt('确认时再次核验组织、成员状态与管理权限。','The organization, member state and management permission are rechecked on confirmation.')}</p><div id="member-error" class="form-error"></div>`,btn('取消','close-modal')+flowButton('确认变更 · 演示','Confirm change · demo','member-save','','primary')+flowButton('演示确认前撤权','Simulate permission withdrawal','member-revoke','','quiet'));};
flowHandlers['member-revoke']=()=>{workspaces[memberIntent.owner].management=false;toast(txt('管理能力已撤回；确认操作将被阻止。','Management capability withdrawn; confirmation will be blocked.'));};
flowHandlers['member-save']=()=>{const error=commitMemberChange();if(error){document.getElementById('member-error').textContent=translateUi(txt('保存未完成，请刷新成员列表后重试。','The change was not saved. Refresh the members list and try again.'));return;}closeModal();render();toast(txt('演示权限已更新。','Demo permission updated.'));};
// A demo panel changes fixtures, never real accounts or services.
actions.demo=()=>{const options=(id,label,values,current)=>`<div class="modal-field"><label for="${id}">${label}</label><select id="${id}">${values.map(([v,z,e])=>`<option value="${v}" ${v===current?'selected':''}>${txt(z,e)}</option>`).join('')}</select></div>`;modal(txt('原型场景演示','Prototype scenarios'),`<p>${txt('所有操作只影响本次原型会话。刷新可恢复初始数据。','All changes affect this prototype session only. Reload to restore sample data.')}</p><div class="demo-fields">${options('flow-membership',txt('可用工作区','Available workspaces'),[['standard','组织与个人','Organization + personal'],['personal-only','仅个人空间','Personal only'],['multiple','多个组织','Multiple organizations'],['unavailable','组织列表失败','Organization list unavailable']],membershipScenario)}${options('flow-role',txt('当前组织角色','Current organization role'),[['publisher','Publisher','Publisher'],['member','Member','Member'],['admin','Admin','Admin']],state.role)}${options('flow-original',txt('下一次原文任务结果','Next original result'),[['published','成功公开','Published'],['partial_media','已公开但图片待补齐','Published with images pending'],['uncertain','结果未知','Outcome unknown'],['failed','明确失败','Failed']],site.originalOutcome)}${options('flow-copy',txt('下一次自动分发结果','Next automatic copy result'),[['published','成功公开','Published'],['uncertain','结果未知','Outcome unknown'],['failed','明确失败','Failed']],site.copyOutcome)}${options('flow-members-load',txt('成员列表','Members list'),[['ready','正常','Ready'],['loading','加载中','Loading'],['failed','加载失败','Failed']],site.membersState)}${options('flow-members-save',txt('权限变更结果','Permission save result'),[['success','正常','Success'],['failure','保存失败','Failed']],site.memberSaveScenario)}${options('flow-privacy',txt('浏览器隐私信号','Browser privacy signal'),[['none','没有附加信号','No additional signal'],['gpc','GPC 开启','GPC enabled'],['dnt','DNT 开启','DNT enabled']],site.privacySignal||'none')}</div><div class="demo-control-grid">${flowButton('切换中文站开通状态','Toggle Chinese provisioning','toggle-zh')}${flowButton('切换管理能力','Toggle management capability','toggle-management')}${flowButton('体验首次登录','Try first sign-in','first-login')}${btn('编辑版本冲突','demo-conflict')}${flowButton('体验原文结果未知','Try an unknown original result','demo-original-unknown')}</div>`,btn('完成','close-modal','primary'),true);};
flowHandlers['toggle-zh']=()=>{site.provisioning[state.workspace].zh=!site.provisioning[state.workspace].zh;closeModal();navigate('settings');render();};
flowHandlers['toggle-management']=()=>{workspaces[state.workspace].management=!workspaces[state.workspace].management;closeModal();render();};
flowHandlers['first-login']=()=>{site.firstVisit=true;site.signedIn=false;site.returnTo='content';closeModal();state.route='login';render();};
flowHandlers['demo-original-unknown']=()=>{closeModal();site.originalOutcome='uncertain';state.route='publish';state.rights=false;render();};
document.addEventListener('change',event=>{const el=event.target;const fields={'flow-original':'originalOutcome','flow-copy':'copyOutcome','flow-members-load':'membersState','flow-members-save':'memberSaveScenario','flow-privacy':'privacySignal'};if(fields[el.id])site[fields[el.id]]=el.value;else if(el.id==='flow-membership')setMembershipScenario(el.value);else if(el.id==='flow-role'&&workspaceKind()==='organization')workspaces[state.workspace].role=el.value;else return;render();});

flowHandlers['open-public-site']=value=>{const [owner,lang]=value.split(':');if(!workspaces[owner]||!isSiteReady(owner,lang))return;guard(()=>{site.publicOwner=owner;site.publicLang=lang;state.route='blog';render();});};
